import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const OUTPUT = resolve(ROOT, 'content/adaptive/tec-escola-core-v5/sociology-institutions.json');
const sourceQuestions = JSON.parse(readFileSync(resolve(ROOT, 'content/adaptive/tec-escola-core-v4/subjects/sociology/questions.json'), 'utf8'))
  .filter((question) => question.primarySkill === 'SOCIOLOGY_EXPLAIN_INSTITUTIONS');
const v9QuestionCatalog = JSON.parse(readFileSync(resolve(ROOT, 'content/adaptive/tec-escola-core-v9/question-expansion-v3.json'), 'utf8'));
const sourceV9Questions = (v9QuestionCatalog.questions ?? v9QuestionCatalog)
  .filter((question) => question.skill === 'SOCIOLOGY_EXPLAIN_INSTITUTIONS');

const rows = [
  ['probe-01','PROBE','EASY','IDENTIFY','SCHOOL_AS_INSTITUTION','Uma escola reúne estudantes e profissionais, define papéis e organiza atividades de aprendizagem por meio de regras e rotinas. O que melhor descreve esse conjunto?','Uma instituição social.',['Apenas o prédio onde as atividades ocorrem.','Um encontro ocasional sem expectativas compartilhadas.','Uma característica natural das pessoas.'],'A escola, como instituição, envolve práticas, papéis e expectativas que organizam a educação; não se reduz ao prédio.','INSTITUTION_AS_BUILDING','Procure as regras, os papéis e as práticas que continuam mesmo quando as pessoas e o local mudam.','INSTITUTION_CONFUSED_WITH_BUILDING'],
  ['probe-02','PROBE','EASY','DISTINGUISH','ONE_TIME_STUDY_GROUP','Quatro colegas se reúnem uma única vez para fazer um trabalho. Só esse encontro já permite afirmar que surgiu uma nova instituição social?','Não; um encontro isolado não basta para mostrar um sistema duradouro de papéis e expectativas.',['Sim; qualquer grupo reunido é uma instituição.','Sim; a tarefa escolar transforma automaticamente o grupo em instituição.','Não; instituições só podem existir em prédios públicos.'],'Um grupo pode existir sem constituir uma instituição. Para essa análise, observamos padrões de regras, papéis e práticas que se mantêm e organizam a vida coletiva.','GROUP_CONFUSED_WITH_INSTITUTION','Pergunte se há um padrão duradouro ou apenas uma atividade pontual.','GROUP_AS_INSTITUTION'],
  ['probe-03','PROBE','EASY','IDENTIFY','FAMILY_CARE_PATTERN','Em diferentes arranjos familiares, pessoas podem combinar quem acompanha uma criança à escola e como as tarefas de cuidado serão divididas. Qual leitura sociológica é mais adequada?','A vida familiar pode organizar papéis e expectativas, embora os arranjos variem entre famílias.',['Existe apenas um modelo familiar que organiza o cuidado.','A divisão do cuidado é determinada biologicamente e não pode mudar.','Uma tarefa combinada por uma família vale como regra para todas.'],'A família é uma instituição social, mas seus formatos e acordos variam. O exemplo não autoriza transformar uma experiência em modelo universal.','FAMILY_AS_SINGLE_FIXED_MODEL','Separe a função social analisada da variedade de formas pelas quais ela pode ser organizada.','FAMILY_AS_UNIVERSAL_TEMPLATE'],
  ['probe-04','PROBE','EASY','IDENTIFY','HEALTHCARE_ROLES','Em um serviço de saúde, usuários, profissionais e gestores ocupam papéis distintos e seguem procedimentos para organizar o atendimento. O exemplo se relaciona principalmente a','Uma instituição social de saúde organizada por papéis e práticas.',['Um fenômeno natural sem participação coletiva.','Uma relação exclusivamente privada entre duas pessoas.','Uma regra que se aplica automaticamente a qualquer serviço do mundo.'],'O atendimento é organizado por papéis, procedimentos e expectativas sociais. O exemplo não afirma que todos os serviços tenham regras idênticas.','HEALTHCARE_AS_PRIVATE_ONLY','Observe como os papéis e os procedimentos coordenam a atividade coletiva.','INSTITUTION_AS_PRIVATE_INTERACTION'],
  ['practice-01','PRACTICE','EASY','DISTINGUISH','SCHOOL_OR_BUILDING','Uma escola muda de prédio, mas mantém a atividade educativa, os papéis de estudantes e docentes e suas rotinas. O que permaneceu?','A instituição educacional pode continuar, apesar da mudança do edifício.',['A instituição desaparece sempre que muda de endereço.','Só o edifício é uma instituição; as práticas não contam.','A mudança prova que as regras nunca existiram.'],'O prédio é um espaço físico; a instituição educacional também inclui práticas e expectativas que podem continuar em outro local.','BUILDING_AS_WHOLE_INSTITUTION','Diferencie o local físico do padrão social que organiza a educação.','BUILDING_AS_INSTITUTION'],
  ['practice-02','PRACTICE','EASY','IDENTIFY','CLASSROOM_ROLE','Na sala de aula, docentes organizam situações de ensino e estudantes participam das atividades. Essa distribuição de posições e expectativas é um exemplo de','Papéis sociais relacionados a uma instituição educacional.',['Uma prova de que todas as pessoas agem do mesmo modo.','Um traço biológico de quem estuda.','Uma sanção aplicada a quem falta.'],'Papel social é um conjunto de expectativas ligado a uma posição em determinada situação. Isso não determina completamente o comportamento individual.','ROLE_CONFUSED_WITH_TRAIT','Identifique a posição e as expectativas associadas a ela, sem tratar a expectativa como comportamento obrigatório de todos.','ROLE_AS_INNATE_TRAIT'],
  ['practice-03','PRACTICE','EASY','DISTINGUISH','SCHOOL_RULE_SCOPE','O regimento de uma escola define como reservar a biblioteca. O que essa regra permite concluir diretamente?','A instituição formalizou um procedimento para aquele contexto escolar.',['Que todas as bibliotecas do país usam o mesmo procedimento.','Que a regra é uma lei nacional por estar escrita.','Que todos os estudantes seguem o procedimento sem exceção.'],'O enunciado identifica uma regra formal de uma escola. Seu alcance não deve ser ampliado sem outra evidência.','LOCAL_RULE_AS_UNIVERSAL','Confira quem estabeleceu a regra e a quem ela se aplica.','INSTITUTIONAL_RULE_AS_UNIVERSAL'],
  ['practice-04','PRACTICE','EASY','DISTINGUISH','SCHOOL_RULE_VS_INSTITUTION','Uma escola estabelece que estudantes devem devolver materiais emprestados no prazo. Qual alternativa separa melhor a regra da instituição?','A regra é uma orientação específica; a instituição educacional é o padrão mais amplo de papéis e práticas.',['A regra e a instituição são exatamente a mesma coisa.','A regra é a instituição inteira porque está escrita.','A instituição só existe quando a regra é aplicada a cada pessoa.'],'Uma regra pode integrar uma instituição, mas não representa por si só todas as relações, funções e práticas que a compõem.','RULE_AS_WHOLE_INSTITUTION','Pense na regra como uma parte do conjunto institucional, não como o conjunto inteiro.','RULE_AS_INSTITUTION'],
  ['practice-05','PRACTICE','MEDIUM','APPLY','EDUCATION_AND_SOCIALIZATION','Uma turma aprende procedimentos para realizar uma assembleia escolar e discutir propostas. Qual processo pode ocorrer junto à aprendizagem do conteúdo das disciplinas?','A socialização em práticas de participação, sem garantir que todos participem da mesma forma.',['Uma mudança biológica causada pela escola.','A eliminação de diferenças de opinião entre estudantes.','A prova de que a assembleia representa toda a sociedade.'],'A participação pode ensinar formas de interação e organização coletiva. O resultado depende das condições concretas e não é automaticamente igual para todos.','SOCIALIZATION_AS_UNIFORM_RESULT','Identifique o que pode ser aprendido na interação e limite a conclusão ao caso descrito.','SOCIALIZATION_AS_IDENTICAL_OUTCOME'],
  ['practice-06','PRACTICE','MEDIUM','COMPARE','FAMILY_ARRANGEMENT_VARIATION','Dois domicílios organizam o cuidado de crianças de formas diferentes: em um, parentes se revezam; no outro, adultos compartilham a tarefa com apoio de uma creche. O que a comparação mostra?','A instituição familiar pode organizar o cuidado por arranjos variados e relacionados a outras instituições.',['Somente o primeiro domicílio tem vida familiar.','A creche substitui automaticamente todos os papéis familiares.','Uma das formas é universalmente correta, independentemente do contexto.'],'Arranjos familiares são diversos e podem se relacionar com serviços educacionais e outras condições. O exemplo não estabelece hierarquia automática.','FAMILY_VARIATION_AS_DEFICIT','Descreva os arranjos observados antes de avaliá-los; não presuma que um representa todas as famílias.','FAMILY_VARIATION_AS_DEFICIT'],
  ['practice-07','PRACTICE','MEDIUM','DISTINGUISH','HEALTH_ORGANIZATION_AND_INSTITUTION','Uma unidade de saúde é uma organização concreta. O sistema de papéis, procedimentos e expectativas que organiza o cuidado pode ser analisado como','Uma instituição social de saúde, da qual organizações concretas podem fazer parte.',['O mesmo que o edifício da unidade, sem relações sociais.','Uma característica pessoal dos profissionais.','Uma garantia de que todos recebem atendimento idêntico.'],'A organização é uma estrutura concreta; instituição social é um padrão mais amplo de relações e práticas. Uma não garante por si só resultados iguais.','ORGANIZATION_AND_INSTITUTION_COLLAPSED','Compare a unidade específica com o padrão social mais amplo que organiza o cuidado.','ORGANIZATION_AS_INSTITUTION'],
  ['practice-08','PRACTICE','MEDIUM','ANALYZE','WORKPLACE_ROLES','Em uma cooperativa, integrantes decidem como distribuir tarefas, registrar decisões e repartir resultados. Qual dimensão sociológica aparece no exemplo?','A instituição econômica organiza relações e expectativas sobre trabalho e recursos.',['Uma relação sem regras ou posições sociais.','Um resultado determinado apenas por talentos individuais.','Uma regra que necessariamente vale para todas as empresas.'],'O trabalho e a distribuição de recursos são organizados por práticas e relações sociais. O exemplo não descreve todas as organizações econômicas.','ECONOMY_AS_INDIVIDUAL_ONLY','Procure as relações coletivas que organizam tarefas e recursos.','ECONOMIC_INSTITUTION_AS_INDIVIDUAL_CHOICE'],
  ['practice-09','PRACTICE','MEDIUM','IDENTIFY','PUBLIC_SERVICE_PROCEDURE','Um órgão público define etapas para solicitar um serviço, identifica responsáveis e informa como acompanhar o pedido. Qual análise é mais precisa?','Há procedimentos institucionais que organizam responsabilidades e acesso ao serviço.',['A presença de etapas prova que ninguém enfrenta barreiras.','O procedimento é uma preferência particular sem dimensão coletiva.','A regra desse órgão se aplica automaticamente a qualquer serviço público.'],'Procedimentos e papéis organizam a ação institucional, mas sua existência não mostra, sozinha, como o acesso ocorre para todas as pessoas.','FORMAL_PROCESS_AS_EQUAL_ACCESS','Separe a regra formal da evidência sobre seus efeitos e seu alcance.','RULE_AS_PROOF_OF_EQUAL_ACCESS'],
  ['practice-10','PRACTICE','MEDIUM','COMPARE','RELIGION_AND_PLURALISM','Uma comunidade organiza encontros e práticas religiosas segundo suas próprias tradições. Qual afirmação evita generalização?','Práticas religiosas podem variar entre comunidades e participantes; o caso descreve apenas o contexto observado.',['Todas as religiões organizam seus encontros do mesmo modo.','A comunidade observada representa todas as pessoas religiosas.','A existência de uma tradição impede qualquer mudança.'],'Instituições religiosas podem organizar práticas e pertencimentos, mas há diversidade entre tradições e dentro delas.','RELIGIOUS_PRACTICE_AS_UNIVERSAL','Delimite a comunidade observada e evite atribuir a mesma prática a todas as pessoas.','RELIGIOUS_UNIVERSALIZATION'],
  ['practice-11','PRACTICE','MEDIUM','DISTINGUISH','TEMPORARY_CAMPAIGN','Uma escola promove uma campanha de arrecadação durante uma semana. Por que a campanha, isoladamente, não prova a criação de uma instituição social?','Porque uma ação temporária não mostra, por si só, um padrão duradouro de papéis e expectativas.',['Porque instituições nunca realizam campanhas.','Porque qualquer campanha é um fenômeno natural.','Porque uma instituição só existe se tiver um nome oficial.'],'Uma atividade pode ocorrer dentro de uma instituição sem constituir uma instituição própria. É preciso observar continuidade e organização social além do evento.','EVENT_AS_INSTITUTION','Pergunte se a atividade cria um padrão social duradouro ou se é uma iniciativa delimitada.','TEMPORARY_EVENT_AS_INSTITUTION'],
  ['practice-12','PRACTICE','MEDIUM','ANALYZE','INSTITUTIONAL_CHANGE','Após ouvir estudantes e famílias, uma escola revê uma regra de comunicação. Qual interpretação é sociologicamente cuidadosa?','A instituição pode mudar práticas por interação e disputa; é preciso avaliar quem participou e os efeitos.',['A mudança prova que nenhuma regra existia antes.','A revisão demonstra que todas as pessoas concordaram.','Instituições são imutáveis e só mudam quando o prédio muda.'],'Instituições são reproduzidas e também podem ser transformadas. Uma revisão não demonstra, sem outras evidências, unanimidade ou efeitos iguais.','CHANGE_AS_UNANIMITY','Identifique a prática alterada, os participantes ouvidos e o que ainda precisa ser observado.','INSTITUTIONAL_CHANGE_AS_UNANIMITY'],
  ['transfer-01','TRANSFER','MEDIUM','APPLY','ACCESSIBLE_SCHOOL_PROCEDURE','Uma escola altera o sistema de inscrição em atividades: passa a oferecer formulário digital e atendimento presencial em horários definidos. O que a mudança procura fazer?','Reorganizar um procedimento institucional para ampliar formas de acesso; o efeito precisa ser verificado.',['Provar que todos conseguem se inscrever igualmente.','Eliminar a necessidade de regras e responsabilidades.','Transformar a escola em uma instituição diferente de um dia para o outro.'],'O procedimento foi alterado e pode reduzir uma barreira, mas é preciso observar quem consegue utilizá-lo e quais dificuldades permanecem.','PROCEDURE_CHANGE_AS_PROVEN_OUTCOME','Diferencie a intenção da mudança dos resultados observados.','POLICY_INTENT_AS_RESULT'],
  ['transfer-02','TRANSFER','MEDIUM','COMPARE','CLINIC_SHIFT_SCHEDULE','Uma clínica muda parte dos horários de atendimento após usuários que trabalham em turnos relatarem dificuldade de comparecer. Qual leitura é melhor?','A organização de horários é uma prática institucional que pode responder a condições de diferentes grupos.',['A mudança prova que todas as barreiras de acesso foram eliminadas.','A dificuldade dos usuários é apenas uma escolha individual sem relação com horários.','A clínica passa a atender todas as pessoas da mesma forma em qualquer situação.'],'Horários organizam o acesso e podem ser revistos diante de necessidades observadas. A medida não permite afirmar que todas as barreiras desapareceram.','INSTITUTIONAL_RESPONSE_AS_COMPLETE_SOLUTION','Relacione a regra de horário à condição relatada e identifique o limite da conclusão.','SINGLE_CHANGE_AS_COMPLETE_SOLUTION'],
  ['transfer-03','TRANSFER','MEDIUM','ANALYZE','FAMILY_CARE_AND_PUBLIC_SERVICE','Uma família reorganiza os turnos de cuidado quando uma pessoa começa a frequentar um curso noturno. Qual fator ajuda a explicar a mudança sem reduzir tudo à vontade individual?','As rotinas familiares se relacionam com papéis e também com condições de outras instituições, como educação e trabalho.',['A família age isolada de horários e serviços sociais.','A mudança comprova que existe um único papel familiar correto.','A instituição familiar impede que seus membros negociem tarefas.'],'A organização do cuidado pode mudar em relação a horários de estudo, trabalho e serviços. Isso não elimina escolhas nem determina um único arranjo.','FAMILY_AS_ISOLATED_OR_FIXED','Observe como rotinas e instituições se relacionam, sem afirmar que uma causa determina todo o resultado.','INSTITUTIONS_AS_ISOLATED'],
  ['transfer-04','TRANSFER','MEDIUM','DISTINGUISH','LIBRARY_ORGANIZATION_AND_READING','Uma biblioteca municipal registra empréstimos, enquanto a educação escolar organiza atividades de ensino. O que a comparação permite dizer?','São organizações e instituições relacionadas, mas com funções e procedimentos que não devem ser confundidos.',['As duas são a mesma organização porque lidam com livros.','A biblioteca substitui automaticamente a escola.','Uma atividade de leitura prova que não há diferenças institucionais.'],'Bibliotecas e escolas podem colaborar na educação, mas têm arranjos e papéis distintos. A semelhança temática não as torna a mesma organização.','RELATED_INSTITUTIONS_AS_IDENTICAL','Compare os objetivos e procedimentos descritos, sem confundir colaboração com identidade.','RELATED_AS_IDENTICAL'],
  ['transfer-05','TRANSFER','MEDIUM','INTERPRET','PUBLIC_DECISION_RESPONSIBILITY','Uma prefeitura registra quem analisou uma solicitação, qual critério foi usado e como pedir revisão. Qual aspecto institucional está mais evidente?','A distribuição de papéis e procedimentos que organiza decisões e permite acompanhar responsabilidades.',['A garantia de que toda decisão será aceita por todos.','A ausência de poder nas relações entre órgãos e usuários.','A prova de que o procedimento não pode ser contestado.'],'Papéis, critérios e revisão organizam decisões. A existência do processo não garante consenso nem impede contestação.','PROCEDURE_AS_CONSENSUS','Identifique quem decide, com base em quais critérios e quais formas de revisão existem.','FORMAL_PROCEDURE_AS_CONSENSUS'],
  ['transfer-06','TRANSFER','MEDIUM','EVALUATE','ONLINE_COMMUNITY_RULES','Uma comunidade digital define como moderar publicações e permite que participantes contestem decisões. Como analisar essa comunidade?','Como um espaço organizado por regras, papéis e relações de poder, cuja aplicação também deve ser examinada.',['Como uma instituição sem relações sociais porque funciona por aplicativo.','Como um espaço em que regras são sempre neutras e aplicadas igualmente.','Como uma instituição que representa todas as comunidades digitais.'],'Tecnologias mediam interações, mas não eliminam organização, papéis ou poder. É necessário observar como as regras são formuladas e aplicadas.','DIGITAL_SPACE_AS_SOCIAL_VOID','Aplique ao ambiente digital as mesmas perguntas sobre regras, papéis, decisões e efeitos.','DIGITAL_AS_NON_SOCIAL'],
  ['transfer-07','TRANSFER','MEDIUM','ANALYZE','UNEQUAL_RULE_ENFORCEMENT','Um regulamento escolar prevê a mesma consequência para todos, mas registros mostram que ela é aplicada com frequências diferentes entre turmas. Qual investigação é necessária?','Examinar como a regra é aplicada, quais situações são comparáveis e que efeitos a diferença produz.',['Concluir que a aplicação é igual porque o texto do regulamento é o mesmo.','Afirmar a intenção de cada profissional sem ouvir ou observar evidências.','Concluir que a instituição deixou de existir.'],'O texto formal não descreve sozinho a prática. Comparar aplicação e efeitos exige contexto e não permite presumir intenções individuais.','WRITTEN_RULE_AS_EQUAL_PRACTICE','Separe o texto da regra dos registros de aplicação e compare situações equivalentes.','WRITTEN_RULE_AS_EQUALITY'],
  ['transfer-08','TRANSFER','MEDIUM','SYNTHESIZE','SCHOOL_TRANSPORT_COORDINATION','Uma escola ajusta o horário de saída depois que o serviço de transporte do bairro muda seus itinerários. O exemplo evidencia que','Práticas de instituições diferentes podem se relacionar e exigir coordenação.',['A escola controla sozinha todas as condições de deslocamento.','O transporte determina sem negociação qualquer rotina escolar.','A mudança prova que as duas instituições têm a mesma função.'],'Educação e transporte podem depender de coordenação, sem que uma instituição controle integralmente a outra ou tenha a mesma função.','INTERDEPENDENCE_AS_CONTROL','Identifique a relação entre as duas rotinas e evite transformar interdependência em controle total.','INTERDEPENDENCE_AS_TOTAL_CONTROL'],
  ['lockin-01','LOCK_IN','HARD','EVALUATE','INSTITUTION_AND_AGENCY','Uma regra de uma instituição influencia as opções disponíveis, mas participantes encontram formas distintas de segui-la, negociá-la ou contestá-la. Qual conclusão é mais adequada?','A instituição estrutura possibilidades, mas não determina mecanicamente cada ação individual.',['A regra não tem qualquer efeito porque as pessoas podem agir de modos diferentes.','Todas as pessoas necessariamente obedecem da mesma maneira.','A instituição só existe se ninguém contestar suas regras.'],'Instituições organizam condições e expectativas; pessoas também interpretam e podem responder de formas diversas.','STRUCTURE_AS_TOTAL_DETERMINISM','Considere ao mesmo tempo as condições institucionais e as respostas dos participantes.','STRUCTURE_AS_DETERMINISM'],
  ['lockin-02','LOCK_IN','HARD','ANALYZE','EQUAL_RULE_DIFFERENT_RESOURCES','Duas escolas adotam o mesmo prazo para entregar uma atividade. Uma oferece laboratório aberto; a outra não dispõe desse recurso. O que deve ser analisado antes de afirmar que a regra produz condições iguais?','Como os recursos e as condições de cada escola afetam a possibilidade de cumprir o prazo.',['A igualdade do texto prova que as condições são iguais.','A diferença de recursos prova que uma escola não tem instituição educacional.','O prazo determina sozinho o resultado de todos os estudantes.'],'Regras iguais no papel podem interagir com condições diferentes. É necessário observar recursos, oportunidades e resultados antes de concluir sobre igualdade.','SAME_RULE_AS_SAME_CONDITION','Compare a regra formal e os recursos disponíveis em cada contexto.','FORMAL_EQUALITY_AS_EQUAL_CONDITIONS'],
  ['lockin-03','LOCK_IN','HARD','DISTINGUISH','SCHOOL_AS_ORGANIZATION_AND_INSTITUTION','Uma escola específica possui direção, funcionários e documentos próprios; a educação também envolve expectativas e práticas sociais presentes em diferentes escolas. Qual distinção é mais precisa?','A escola específica é uma organização; a educação pode ser analisada como instituição social mais ampla.',['A organização concreta e a instituição mais ampla são idênticas em todos os sentidos.','Só documentos fazem parte de instituições sociais.','A educação deixa de ser instituição quando uma escola fecha.'],'A organização concreta tem estrutura e participantes delimitados; a instituição se refere a padrões mais amplos. Uma organização pode expressar uma instituição sem esgotá-la.','ORGANIZATION_EQUALS_INSTITUTION','Use “organização” para a estrutura concreta e “instituição” para o padrão social mais amplo.','ORGANIZATION_INSTITUTION_COLLAPSED'],
  ['lockin-04','LOCK_IN','HARD','ANALYZE','INSTITUTIONAL_CHANGE_AND_CONFLICT','Usuários contestam uma regra de atendimento; depois de reuniões, uma instituição altera o procedimento e cria um canal de revisão. O que a sequência sustenta?','Conflitos e participação podem contribuir para mudanças institucionais; a adesão e os efeitos ainda precisam ser observados.',['A mudança prova que todos concordaram com a regra nova.','A contestação demonstra que a instituição nunca existiu.','O novo procedimento elimina qualquer conflito futuro.'],'A sequência mostra mudança após contestação, mas não permite inferir consenso total nem prever que novos conflitos não ocorrerão.','CHANGE_AS_CONSENSUS_OR_FINALITY','Distinga a mudança registrada de conclusões sobre consenso e efeitos futuros.','CHANGE_AS_FINAL_CONSENSUS'],
  ['lockin-05','LOCK_IN','HARD','EVALUATE','INSTITUTIONAL_FUNCTIONS_AND_EFFECTS','Uma instituição declara que sua regra busca ampliar a participação. Algumas pessoas relatam que ainda encontram obstáculos. Qual avaliação é mais adequada?','Comparar objetivo declarado, procedimento e efeitos para diferentes participantes.',['Considerar o objetivo declarado prova suficiente de que a participação aumentou.','Descartar os relatos porque a regra formal é igual.','Afirmar sem investigação que a instituição pretende excluir essas pessoas.'],'Objetivos, regras e efeitos são dimensões diferentes. A avaliação exige evidências sobre a experiência dos participantes e evita presumir intenção.','DECLARED_PURPOSE_AS_PROVEN_EFFECT','Pergunte o que a instituição declara, o que faz e o que os dados mostram sobre os efeitos.','DECLARED_GOAL_AS_OUTCOME'],
  ['lockin-06','LOCK_IN','HARD','SYNTHESIZE','INTERDEPENDENT_INSTITUTIONS_ACCESS','Uma mudança no horário de uma escola afeta o transporte disponível e a organização do cuidado em alguns domicílios. Qual explicação evita uma causa única?','As rotinas de educação, transporte e cuidado se relacionam; seus efeitos variam conforme recursos e contextos.',['A escola determina sozinha todas as rotinas familiares e de transporte.','As instituições não têm relação porque possuem nomes diferentes.','Um efeito observado em alguns domicílios vale necessariamente para todos.'],'Instituições podem ser interdependentes, mas as relações e os efeitos variam. A observação não sustenta uma explicação única nem uma generalização universal.','INTERDEPENDENCE_AS_SINGLE_CAUSE','Mapeie as instituições relacionadas e identifique quais grupos e condições foram observados.','INTERDEPENDENCE_AS_UNIVERSAL_CAUSE'],
  ['review-01','REVIEW','EASY','IDENTIFY','SCHOOL_ROLES_RECALL','Uma escola organiza atividades com papéis de estudantes e docentes e expectativas compartilhadas. Esse conjunto pode ser estudado como','Uma instituição social.',['Um prédio sem relações sociais.','Uma característica natural imutável.','Um acontecimento sem continuidade.'],'Papéis e expectativas que organizam práticas coletivas são parte da análise institucional.','INSTITUTION_AS_BUILDING','Procure os padrões de relação, não apenas o local.','INSTITUTION_CONFUSED_WITH_BUILDING'],
  ['review-02','REVIEW','EASY','DISTINGUISH','ORGANIZATION_RECALL','Uma associação local tem nome, integrantes e tarefas definidos. Qual termo descreve melhor essa estrutura concreta?','Organização.',['Instituição social em todos os sentidos, sem distinção possível.','Regra informal.','Papel social individual.'],'Uma organização é uma estrutura concreta de participantes e tarefas; ela pode se relacionar com instituições mais amplas.','ORGANIZATION_AND_INSTITUTION_COLLAPSED','Pense se a pergunta fala de uma estrutura delimitada ou de um padrão social amplo.','ORGANIZATION_AS_INSTITUTION'],
  ['review-03','REVIEW','MEDIUM','DISTINGUISH','RULE_AS_PART_OF_INSTITUTION','Uma instituição altera uma regra de empréstimo, mas mantém os papéis de usuários e responsáveis pelo serviço. O que mudou no exemplo?','Um procedimento específico, não necessariamente toda a instituição.',['A instituição inteira desapareceu no instante da mudança.','O prédio virou uma regra formal.','Todos os participantes mudaram de papel automaticamente.'],'Uma instituição pode revisar práticas sem deixar de existir; é preciso observar o conjunto mais amplo de relações.','RULE_CHANGE_AS_INSTITUTION_END','Identifique o elemento alterado e o que permaneceu organizado.','RULE_CHANGE_AS_INSTITUTION_END'],
  ['review-04','REVIEW','MEDIUM','INTERPRET','CARE_ROLE_NEGOTIATION','Em um domicílio, adultos renegociam quem fará uma tarefa de cuidado depois que os horários de trabalho mudam. Qual leitura é mais adequada?','Papéis e rotinas podem ser negociados diante de novas condições sociais.',['O cuidado pertence naturalmente a uma única pessoa.','A mudança prova que os vínculos familiares terminaram.','O horário de trabalho não pode se relacionar com práticas familiares.'],'Papéis sociais e rotinas podem mudar; o exemplo não autoriza atribuir uma tarefa por natureza a um integrante.','CARE_ROLE_AS_NATURAL','Relacione a mudança de horário à reorganização observada, sem generalizar o arranjo.','CARE_ROLE_AS_NATURAL'],
  ['review-05','REVIEW','MEDIUM','APPLY','HEALTH_ACCESS_CHECK','Um serviço de saúde cria um canal de agendamento por telefone além do aplicativo. Que evidência ajudaria a avaliar o efeito da mudança?','Dados ou relatos sobre quem conseguiu agendar por cada canal e quais barreiras persistiram.',['Apenas a existência do novo canal.','A opinião de uma única pessoa tratada como resultado de todos.','O número de downloads do aplicativo, sem relação com agendamentos.'],'A mudança formal não prova seu efeito. É preciso acompanhar o acesso de diferentes usuários e os obstáculos restantes.','NEW_CHANNEL_AS_ACCESS_PROOF','Procure evidências de uso e de acesso entre os grupos afetados.','PROCEDURE_AS_OUTCOME'],
  ['review-06','REVIEW','MEDIUM','DISTINGUISH','INSTITUTION_VS_EVENT_RECALL','Um festival anual reúne voluntários e segue um planejamento próprio. O que é necessário para analisar se ele se tornou uma instituição social?','Investigar continuidade, papéis, regras e expectativas para além de uma edição do evento.',['Basta saber que houve muitas pessoas em uma edição.','É suficiente que o festival tenha um nome.','Qualquer evento é uma instituição por definição.'],'Um evento pode adquirir padrões duradouros, mas isso deve ser sustentado por evidências de continuidade e organização.','EVENT_AS_INSTITUTION','Busque evidência sobre repetição, papéis e expectativas ao longo do tempo.','EVENT_AS_INSTITUTION'],
  ['review-07','REVIEW','MEDIUM','ANALYZE','INSTITUTIONS_AND_EQUALITY_RECALL','Uma regra pública usa os mesmos critérios para solicitar um benefício, mas parte dos moradores não consegue concluir o processo. O que investigar?','Como informação, recursos, etapas e atendimento afetam o acesso de diferentes grupos.',['Concluir que o critério é justo apenas porque está escrito da mesma forma.','Afirmar que todos os moradores desistiram pela mesma razão.','Concluir que o serviço não tem qualquer dimensão institucional.'],'A formulação da regra é apenas uma parte da análise; condições de acesso e efeitos precisam ser observados.','SAME_CRITERIA_AS_EQUAL_ACCESS','Examine etapas e condições práticas para além do texto formal.','FORMAL_RULE_AS_EQUAL_ACCESS'],
  ['review-08','REVIEW','HARD','EVALUATE','ROLE_EXPECTATION_AND_PERSON','Uma pessoa ocupa o papel de estudante e também participa de um grupo esportivo. As expectativas de cada situação podem diferir. Qual conclusão é correta?','Papéis são situados; nenhum deles resume completamente a identidade ou as escolhas da pessoa.',['A pessoa precisa agir da mesma maneira em todos os contextos.','Um papel elimina automaticamente os demais.','As diferenças provam que as instituições não influenciam comportamentos.'],'Expectativas variam por contexto e podem coexistir. Papéis influenciam interações, mas não definem toda a pessoa.','ROLE_AS_TOTAL_IDENTITY','Compare a situação e as expectativas de cada papel sem reduzir a pessoa a um só.','ROLE_AS_TOTAL_IDENTITY'],
  ['review-09','REVIEW','HARD','SYNTHESIZE','INSTITUTIONAL_EVIDENCE_RECALL','Uma equipe afirma que uma instituição “sempre exclui” determinado grupo, mas apresenta apenas um relato individual. Qual conclusão respeita o alcance da evidência?','O relato identifica uma experiência que merece investigação, mas não basta para sustentar a afirmação geral.',['A afirmação geral está provada porque o relato é verdadeiro.','O relato deve ser ignorado porque é individual.','A instituição é necessariamente inclusiva porque tem regras escritas.'],'Uma experiência individual é relevante, mas uma afirmação geral exige evidências adicionais e análise de contexto, aplicação e efeitos.','SINGLE_CASE_AS_GENERAL_PATTERN','Valorize o relato e indique que dados ajudariam a verificar a extensão do padrão.','SINGLE_CASE_AS_GENERALIZATION'],
  ['review-10','REVIEW','HARD','EVALUATE','INSTITUTIONAL_CHANGE_RECALL','Uma instituição muda uma rotina depois de participantes apontarem dificuldades. O que se pode afirmar sem extrapolar?','Uma prática foi revista após essas manifestações; consenso e efeitos ainda precisam ser avaliados.',['Todas as pessoas apoiaram a mudança.','A nova rotina resolverá toda dificuldade.','A mudança demonstra que a instituição nunca teve regras.'],'A sequência informa que houve revisão e quais manifestações a antecederam. Não revela automaticamente a opinião de todos nem os resultados futuros.','CHANGE_AS_UNANIMITY','Registre a mudança observada e separe dela hipóteses ainda não verificadas.','CHANGE_AS_UNANIMITY'],
];

